def seed_full_question_bank():
    conn = sqlite3.connect(DB_PATH)
    cur = conn.cursor()
    now = datetime.utcnow().isoformat()

    total_added = 0

    for subject_id, diff_dict in QUESTIONS_DATA.items():
        # Get units for this subject
        cur.execute("SELECT id, unit_number FROM units WHERE subject_id = ? ORDER BY unit_number", (subject_id,))
        units = cur.fetchall()
        unit_ids = [u[0] for u in units] if units else [None]

        for difficulty, questions in diff_dict.items():
            for i, (text, options, answer, explanation) in enumerate(questions):
                # Pick a unit round-robin
                assigned_unit_id = unit_ids[i % len(unit_ids)] if unit_ids[0] else None

                # Check if question with exact text already exists
                cur.execute("SELECT id FROM questions WHERE question_text = ?", (text,))
                if cur.fetchone():
                    continue

                options_json = json.dumps(options)
                cur.execute("""
                    INSERT INTO questions (
                        subject_id, unit_id, question_text, difficulty,
                        options_json, correct_answer, explanation,
                        source_reference, is_active, is_approved,
                        created_by_id, approved_by_id, created_at, updated_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1, 1, 1, 1, ?, ?)
                """, (
                    subject_id, assigned_unit_id, text, difficulty,
                    options_json, answer, explanation,
                    "MBA Semester 1 Academic Examination Council Question Bank",
                    now, now
                ))
                total_added += 1

    conn.commit()
    print(f"Full question bank seeded successfully! Added {total_added} new questions.")

    # Print summary per subject and difficulty
    cur.execute("""
        SELECT s.id, s.name, q.difficulty, count(q.id)
        FROM subjects s
        JOIN questions q ON s.id = q.subject_id AND q.is_active=1 AND q.is_approved=1
        GROUP BY s.id, q.difficulty
        ORDER BY s.id, q.difficulty
    """)
    rows = cur.fetchall()
    print("\nUpdated Question Distribution by Subject and Difficulty:")
    current_sid = None
    for sid, sname, diff, count in rows:
        if sid != current_sid:
            print(f"\nSubject {sid}: {sname}")
            current_sid = sid
        print(f"  {diff}: {count} questions")

    conn.close()

if __name__ == "__main__":
    seed_full_question_bank()
